import orders from './orders.json' with { type: 'json' };

const TOOLS = [
  {
    name: 'order_status',
    description: 'Get the current status of an order, with optional history.',
    inputSchema: {
      type: 'object',
      properties: {
        order_id: { type: 'string' },
        include_history: { type: 'boolean', default: false },
      },
      required: ['order_id'],
      additionalProperties: false,
    },
  },
];

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args) {
  if (name !== 'order_status') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Reject extra fields (additionalProperties is declared, but we enforce manually)
  const allowed = new Set(['order_id', 'include_history']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown field: ${key}`);
    }
  }

  const order_id = args.order_id;
  if (!order_id || typeof order_id !== 'string') {
    throw new Error('Missing or invalid order_id');
  }

  const order = orders[order_id];
  if (!order) {
    throw new Error(`Order not found: ${order_id}`);
  }

  const include_history = args.include_history === true;

  let text = `Order ${order_id} status: ${order.status}`;
  if (include_history) {
    text += ` | History: ${order.history.join(' -> ')}`;
  }

  return { content: [{ type: 'text', text }] };
}
